/* 尾文字Z V46: original high-detail OBJ-derived mesh pack. Not extracted from other games. */
(function(){'use strict';
 const pack={"body":"","sunshine":"","rally":"","midnight":"","royal":""};
 const palette=[[20,24,30,1],[41,44,56,1],[10,13,18,1],[77,82,195,0.77],[100,107,234,0.78],[35,44,118,0.86],[9,11,15,1],[21,28,38,1],[52,57,64,1],[37,42,48,1],[21,25,30,1],[36,39,43,1],[149,159,170,1],[197,210,220,1],[244,246,234,1],[247,202,86,1],[184,25,53,1],[231,142,54,1],[101,63,192,1],[212,175,89,1],[242,231,202,1],[125,139,147,1],[34,39,52,1],[242,198,51,1],[255,224,102,1],[186,131,42,1],[92,140,204,0.8],[160,200,238,0.8],[186,200,198,1],[249,238,211,1],[33,108,186,1],[169,40,58,1],[83,52,133,1],[24,41,68,1],[247,214,123,1],[159,109,237,1]];
 const cache=Object.create(null);
 function decode(name){
  if(cache[name])return cache[name];const encoded=pack[name];if(!encoded)return null;
  const raw=atob(encoded);if(raw.length%19)throw Error('Model binary payload is invalid');
  const binary=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)binary[i]=raw.charCodeAt(i);
  const view=new DataView(binary.buffer);const f=new Float32Array(raw.length/19*36);let pos=0;
  for(let t=0;t<raw.length/19;t++){
   const p=t*19;const verts=[];
   for(let i=0;i<3;i++)verts.push([view.getInt16(p+i*6,true)/1000,view.getInt16(p+i*6+2,true)/1000,view.getInt16(p+i*6+4,true)/1000]);
   const a=verts[0],b=verts[1],c=verts[2];const u=b.map((x,i)=>x-a[i]),v=c.map((x,i)=>x-a[i]);
   let nx=u[1]*v[2]-u[2]*v[1],ny=u[2]*v[0]-u[0]*v[2],nz=u[0]*v[1]-u[1]*v[0],mag=Math.hypot(nx,ny,nz)||1;
   nx/=mag;ny/=mag;nz/=mag;
   const rgba=palette[view.getUint8(p+18)];if(!rgba)throw Error('Material out of range');
   for(const xyz of verts){f.set([xyz[0],xyz[1],xyz[2],nx,ny,nz,rgba[0]/255,rgba[1]/255,rgba[2]/255,rgba[3],0,1],pos);pos+=12;}
  }
  return cache[name]={data:f,count:pos/12,triangles:pos/36,length:3.2,width:2.05,height:1.79,original:true};
 }
 window.OMZ_YB_MODELS=Object.freeze({decode,names:Object.keys(pack),version:'V46',source:'Original OBJ procedural reconstruction'});
})();
